const zone = 'Asia/Dubai';
const todayStart = $now.setZone(zone).startOf('day');
const p_end = todayStart.toISO();
const p_start = todayStart.minus({ days: 1 }).toISO();
return [{ json: { p_start, p_end, zone } }];

const resp = ($json.body !== undefined) ? $json.body : $json;
const s = Array.isArray(resp) ? (resp[0] || {}) : (resp || {});
const intent = s.by_intent || {};
const tier = s.by_tier || {};
const fmtMap = (m) => { const ks = Object.keys(m); return ks.length ? ks.map(k => k + ': ' + m[k]).join('   ') : 'none'; };
const start = s.window_start ? String(s.window_start).slice(0, 10) : '';
const received = s.leads_received || 0;
const handedOff = s.handed_off || 0;
const qualifying = s.qualifying || 0;
const dead = s.dead || 0;
const runsTotal = s.runs_total || 0;
const runsPartial = s.runs_partial || 0;
const runsFailed = s.runs_failed || 0;
const errors = s.errors || [];

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: 'Daily lead digest - ' + start, emoji: false } },
  { type: 'section', fields: [
    { type: 'mrkdwn', text: '*Leads received:*\n' + received },
    { type: 'mrkdwn', text: '*Handed off to agents:*\n' + handedOff },
    { type: 'mrkdwn', text: '*Still qualifying:*\n' + qualifying },
    { type: 'mrkdwn', text: '*Closed (no reply / opt-out):*\n' + dead }
  ]},
  { type: 'section', fields: [
    { type: 'mrkdwn', text: '*By intent:*\n' + fmtMap(intent) },
    { type: 'mrkdwn', text: '*By tier (scored):*\n' + fmtMap(tier) }
  ]},
  { type: 'section', fields: [
    { type: 'mrkdwn', text: '*Runs logged:*\n' + runsTotal },
    { type: 'mrkdwn', text: '*Partial / Failed:*\n' + runsPartial + ' / ' + runsFailed }
  ]}
];
if (errors.length) {
  const lines = errors.slice(0, 5).map(e => '- ' + (e.workflow || '?') + ' / ' + (e.step || '?') + ' - ' + String(e.error || '').slice(0, 120)).join('\n');
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '*Failures:*\n' + lines } });
} else {
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: 'No failed runs in the window.' }] });
}

const text = 'Daily lead digest ' + start + ': ' + received + ' leads, ' + handedOff + ' handed off, ' + runsFailed + ' failures';
const slack_body = { channel: '#leads', text: text, blocks: blocks };
return [{ json: { slack_body, stats: s } }];
